// This file is generated by AI.

// 角色选择对话框: 只负责"挑选参与配音的角色"。
//
// 勾选启用、星标靠前、导入。**不做**角色信息编辑 —— 参考音频一类的编辑在工作台的
// 「编辑角色」对话框里, 那里才有足够空间。在这里点一行就跳去编辑别的对话框既不符合
// 直觉, 也让这个对话框的职责变得含糊。

import { Button, Checkbox, Input } from '@fluentui/react-components';
import {
  ArrowDownloadRegular,
  ArrowUploadRegular,
  DeleteRegular,
  FolderOpenRegular,
  StarFilled,
  StarRegular,
} from '@fluentui/react-icons';
import { save as saveDialog } from '@tauri-apps/plugin-dialog';
import { useEffect, useMemo, useState } from 'react';

import type { Character } from '../commands/voice';
import { voiceExportCharacter } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { ListImportDialog } from './ListImportDialog';

interface Props {
  open: boolean;
  onClose: () => void;
  onError: (error: string | null) => void;
}

export function RolePickerDialog({ open, onClose, onError }: Props) {
  const characters = useAppStore((state) => state.voiceCharacters);
  const [query, setQuery] = useState('');
  const [message, setMessage] = useState<string | null>(null);
  const [listImportOpen, setListImportOpen] = useState(false);

  useEffect(() => {
    if (open) {
      setQuery('');
      setMessage(null);
    }
  }, [open]);

  const visible = useMemo(() => {
    if (!query.trim()) return characters;
    const needle = query.trim().toLowerCase();
    return characters.filter(
      (character) => character.name.toLowerCase().includes(needle) || character.id.toLowerCase().includes(needle)
    );
  }, [characters, query]);

  if (!open) return null;

  const report = (caught: unknown) => onError(caught instanceof Error ? caught.message : String(caught));

  const toggleEnabled = async (character: Character, enabled: boolean) => {
    try {
      await voiceController.persistCharacter({ ...character, enabled });
    } catch (caught) {
      report(caught);
    }
  };

  const toggleStarred = async (character: Character, starred: boolean) => {
    try {
      await voiceController.persistCharacter({ ...character, starred });
    } catch (caught) {
      report(caught);
    }
  };

  /** 导入一份角色 zip */
  const importCharacter = async () => {
    setMessage(null);
    try {
      await voiceController.importCharacter();
    } catch (caught) {
      report(caught);
    }
  };

  const remove = async (character: Character) => {
    try {
      await voiceController.deleteCharacter(character.id);
    } catch (caught) {
      report(caught);
    }
  };

  const exportCharacter = async (character: Character) => {
    const destination = await saveDialog({
      defaultPath: `${character.name}.zip`,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof destination !== 'string') return;
    await voiceExportCharacter(character.id, destination);
  };

  return (
    <>
      <AppDialog
        title="选择角色"
        description="勾选参与配音的角色。角色信息请在「编辑角色」里改。"
        size="large"
        height={600}
        compact
        onClose={onClose}
        footer={
          <Button appearance="secondary" onClick={onClose}>
            关闭
          </Button>
        }
      >
        {/* 工具栏: 搜索占满剩余宽度, 两个导入按钮固定宽度, 因此不会换行 */}
        <div className="dialog-toolbar">
          <Input
            className="dialog-toolbar-grow"
            placeholder="搜索角色…"
            value={query}
            onChange={(_, data) => setQuery(data.value)}
          />
          <Button appearance="secondary" icon={<ArrowUploadRegular />} onClick={() => void importCharacter()}>
            导入角色
          </Button>
          <Button
            appearance="secondary"
            icon={<FolderOpenRegular />}
            title="从训练切分产物的文本清单与音频批量导入角色"
            onClick={() => setListImportOpen(true)}
          >
            从清单导入
          </Button>
        </div>

        {message && <p className="dialog-message">{message}</p>}

        <div className="character-grid character-grid-pick dialog-scroll">
          {visible.length === 0 && <p className="voice-dialog-empty">没有匹配的角色。</p>}
          {visible.map((character) => (
            <div key={character.id} className={`character-block${character.enabled ? '' : ' disabled'}`}>
              <Checkbox
                checked={character.enabled}
                onChange={(_, data) => void toggleEnabled(character, Boolean(data.checked))}
                title="是否参与配音"
              />
              <div className="character-block-main" title="角色信息与参考音频请在配音工作台的角色列表里编辑">
                <span className="character-block-name">{character.name}</span>
                <span className="character-block-meta">
                  {character.id} · 参考音频 {character.references.length}
                  {!character.enabled && ' · 未启用'}
                </span>
              </div>
              <Button
                size="small"
                appearance="subtle"
                title={character.starred ? '取消星标' : '星标靠前'}
                icon={character.starred ? <StarFilled /> : <StarRegular />}
                onClick={() => void toggleStarred(character, !character.starred)}
              />
              <Button
                size="small"
                appearance="subtle"
                title="导出角色"
                icon={<ArrowDownloadRegular />}
                onClick={() => void exportCharacter(character)}
              />
              <Button
                size="small"
                appearance="subtle"
                className="danger-icon"
                title="删除角色"
                icon={<DeleteRegular />}
                onClick={() => void remove(character)}
              />
            </div>
          ))}
        </div>
      </AppDialog>

      {listImportOpen && (
        <ListImportDialog
          onClose={() => setListImportOpen(false)}
          onImported={setMessage}
          onError={(error) => {
            if (error) report(error);
          }}
        />
      )}
    </>
  );
}
